insert into fitness_exercises (name, kind, equipment, muscles, measure, reps, seconds, each_side, picture, steps) values
  ('Chin-up', 'strength', '{body}', '{back,arms}', 'reps', 10, null, false, 'Chin-Up', array['Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.', 'As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
  ('Pull-up', 'strength', '{body}', '{back,arms}', 'reps', 10, null, false, 'Pullups', array['Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
  ('Inchworm', 'mobility', '{body}', '{legs}', 'hold', null, 30, false, 'Inchworm', array['Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.', 'Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.', 'Keep going until your body is parallel to the ground in a pushup position.', 'Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.', 'Continue walking until your feet are by hour hands, keeping your legs straight as you do so.']::text[]),
  ('3/4 sit-up', 'strength', '{body}', '{core}', 'reps', 10, null, false, '3_4_Sit-Up', array['Lie down on the floor and secure your feet. Your legs should be bent at the knees.', 'Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position.', 'Flex your hips and spine to raise your torso toward your knees.', 'At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Hack squat', 'strength', '{gym}', '{legs,glutes}', 'reps', 10, null, false, 'Hack_Squat', array['Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.', 'Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.', 'Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).', 'Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).', 'Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your to...', 'Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Chair squat', 'strength', '{gym}', '{legs,glutes}', 'reps', 10, null, false, 'Chair_Squat', array['To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders.', 'Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs.', 'Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position.', 'Slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper and lower leg breaks 90 degrees.', 'Begin to raise the bar as you exhale by pushing the floor with the heels of your feet, extending the knees and returning to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Dip machine', 'strength', '{gym}', '{arms,chest,shoulders}', 'reps', 10, null, false, 'Dip_Machine', array['Sit securely in a dip machine, select the weight and firmly grasp the handles.', 'Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.', 'As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.', 'Now slowly let your arms come back up to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Inverted row', 'strength', '{body}', '{back}', 'reps', 10, null, false, 'Inverted_Row', array['Position a bar in a rack to about waist height. You can also use a smith machine.', 'Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.', 'Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.', 'Pause at the top of the motion, and return yourself to the start position.', 'Repeat for the desired number of repetitions.']::text[]),
  ('Pull through', 'strength', '{gym}', '{glutes,legs,back}', 'reps', 10, null, false, 'Pull_Through', array['Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.', 'Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.']::text[]),
  ('Push-up wide', 'strength', '{body}', '{chest,core,shoulders,arms}', 'reps', 10, null, false, 'Push-Up_Wide', array['With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.', 'To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.', 'After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('V-bar pullup', 'strength', '{body}', '{back,arms,shoulders}', 'reps', 10, null, false, 'V-Bar_Pullup', array['Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles.', 'Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position.', 'Using your lats, pull your torso up while leaning your head back slightly so that you do not hit yourself with the chin-up bar. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion.', 'After a second hold on the contracted position, slowly lower your body back to the starting position as you breathe in.', 'Repeat for the prescribed number of repetitions.']::text[]),
  ('Dumbbell squat', 'strength', '{dumbbells}', '{legs,glutes,back}', 'reps', 10, null, false, 'Dumbbell_Squat', array['Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Glute kickback', 'strength', '{body}', '{glutes,legs}', 'reps', 10, null, true, 'Glute_Kickback', array['Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.', 'As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.', 'Go back to the initial position as you inhale and now repeat with the left leg.', 'Continue to alternate legs until all of the recommended repetitions have been performed.']::text[]),
  ('Vertical swing', 'cardio', '{dumbbells}', '{legs,glutes,shoulders}', 'hold', null, 30, false, 'Vertical_Swing', array['Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up.', 'Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly.', 'Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head.', 'As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition.']::text[]),
  ('Cable deadlifts', 'strength', '{gym}', '{legs,arms,glutes,back}', 'reps', 10, null, false, 'Cable_Deadlifts', array['Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights.', 'To begin, squat down be flexing your hips and knees until you can reach the handles.', 'After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement.', 'After reaching a full standing position, Return to the starting position and repeat.']::text[]),
  ('Decline push-up', 'strength', '{body}', '{chest,shoulders,arms}', 'reps', 10, null, false, 'Decline_Push-Up', array['Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.', 'Next, lower yourself downward until your chest almost touches the floor as you inhale.', 'Now breathe out and press your upper body back up to the starting position while squeezing your chest.', 'After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.']::text[]),
  ('Dumbbell lunges', 'strength', '{dumbbells}', '{legs,glutes}', 'reps', 10, null, true, 'Dumbbell_Lunges', array['Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.', 'Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.', 'Using mainly the heel of your foot, push up and go back to the starting position as you exhale.', 'Repeat the movement for the recommended amount of repetitions and then perform with the left leg.']::text[]),
  ('Band good morning', 'strength', '{bands}', '{legs,glutes,back}', 'reps', 10, null, false, 'Band_Good_Morning', array['Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position.', 'Keeping your legs straight, extend through the hips to come to a near vertical position.', 'Ensure that you do not round your back as you go down back to the starting position.']::text[]),
  ('Cable chest press', 'strength', '{gym}', '{chest,shoulders,arms}', 'reps', 10, null, false, 'Cable_Chest_Press', array['Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position.', 'Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.', 'After pausing at full extension, return to th starting position, keeping tension on the cables.', 'You can also execute this movement with your back off the pad, at an incline or decline, or alternate hands.']::text[]),
  ('One knee to chest', 'mobility', '{body}', '{glutes,legs,back}', 'hold', null, 30, true, 'One_Knee_To_Chest', array['Start off by lying on the floor.', 'Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.', 'Gently tug that knee toward your nose.', 'Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.']::text[]),
  ('Hip lift with band', 'strength', '{bands}', '{glutes,legs}', 'reps', 10, null, false, 'Hip_Lift_with_Band', array['After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move.', 'Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.', 'Keeping your shoulders on the ground, drive through your heels to raise your hips, pushing into the band as high as you can.', 'Pause at the top of the motion, and return to the starting position.']::text[]),
  ('Machine bench press', 'strength', '{gym}', '{chest,shoulders,arms}', 'reps', 10, null, false, 'Machine_Bench_Press', array['Sit down on the Chest Press Machine and select the weight.', 'Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.', 'Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.', 'Now bring the handles back towards you as you breathe in.', 'Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.', 'Repeat for the recommended amount of reps.', 'When finished step on the lever again and slowly get the handles back to their original place.']::text[]),
  ('Plié dumbbell squat', 'strength', '{dumbbells}', '{legs,core,glutes}', 'reps', 10, null, false, 'Plie_Dumbbell_Squat', array['Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent.', 'Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position.', 'Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise.', 'Press mainly with the heel of the foot to bring the body back to the starting position while exhaling.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Standing cable lift', 'strength', '{gym}', '{core,shoulders}', 'reps', 10, null, false, 'Standing_Cable_Lift', array['Connect a standard handle on a tower, and move the cable to the lowest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle up and across your body until your arms are in a fully-extended position above your head.', 'Keep your back straight and your arms close to your body as you pivot your back foot and straighten your legs to get a full range of motion.', 'Retract your arms and then your body. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
  ('Upright barbell row', 'strength', '{gym}', '{shoulders,back}', 'reps', 10, null, false, 'Upright_Barbell_Row', array['Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position.', 'Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should drive the motion, and should always be higher than your forearms. Remember to keep your torso stationary and pause for a second at the top of the movement.', 'Lower the bar back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Cable Russian twists', 'strength', '{gym}', '{core}', 'reps', 10, null, false, 'Cable_Russian_Twists', array['Connect a standard handle attachment, and position the cable to a middle pulley position.', 'Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.', 'Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.', 'Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.', 'Repeat the same movement to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
  ('Cable shoulder press', 'strength', '{gym}', '{shoulders,arms}', 'reps', 10, null, false, 'Cable_Shoulder_Press', array['Move the cables to the bottom of the towers and select an appropriate weight.', 'Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.', 'Keeping your head and chest up, extend through the elbow to press the handles directly over head.', 'After pausing at the top, return to the starting position and repeat.']::text[]),
  ('Dumbbell bench press', 'strength', '{dumbbells}', '{chest,shoulders,arms}', 'reps', 10, null, false, 'Dumbbell_Bench_Press', array['Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.', 'Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
  ('Dumbbell incline row', 'strength', '{dumbbells}', '{back,arms,shoulders}', 'reps', 10, null, false, 'Dumbbell_Incline_Row', array['Using a neutral grip, lean into an incline bench.', 'Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.', 'Retract the shoulder blades and flex the elbows to row the dumbbells to your side.', 'Pause at the top of the motion, and then return to the starting position.']::text[]),
  ('Incline push-up wide', 'strength', '{body}', '{chest,core,shoulders,arms}', 'reps', 10, null, false, 'Incline_Push-Up_Wide', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands wider than shoulder width.', 'Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
  ('One arm lat pulldown', 'strength', '{gym}', '{back,arms}', 'reps', 10, null, true, 'One_Arm_Lat_Pulldown', array['Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position.', 'Pull the handle down, squeezing your elbow to your side as you flex the elbow.', 'Pause at the bottom of the motion, and then slowly return the handle to the starting position.', 'For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.']::text[]),
  ('Barbell walking lunge', 'strength', '{gym}', '{legs,glutes}', 'reps', 10, null, true, 'Barbell_Walking_Lunge', array['Begin standing with your feet shoulder width apart and a barbell across your upper back.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[]),
  ('Bent over barbell row', 'strength', '{gym}', '{back,arms,shoulders}', 'reps', 10, null, false, 'Bent_Over_Barbell_Row', array['Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', 'Then inhale and slowly lower the barbell back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Seated dumbbell press', 'strength', '{dumbbells}', '{shoulders,arms}', 'reps', 10, null, false, 'Seated_Dumbbell_Press', array['Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.', 'Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.', 'Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.', 'As you exhale, push the dumbbells up until they touch at the top.', 'After a second pause, slowly come down back to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Decline dumbbell flyes', 'strength', '{dumbbells}', '{chest}', 'reps', 10, null, false, 'Decline_Dumbbell_Flyes', array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('Dips, triceps version', 'strength', '{body}', '{arms,chest,shoulders}', 'reps', 10, null, false, 'Dips_-_Triceps_Version', array['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.', 'Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.', 'Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('Incline dumbbell flyes', 'strength', '{dumbbells}', '{chest,shoulders}', 'reps', 10, null, false, 'Incline_Dumbbell_Flyes', array['Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.', 'Extend your arms above you with a slight bend at the elbows.', 'Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.', 'As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.', 'As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Incline dumbbell press', 'strength', '{dumbbells}', '{chest,shoulders,arms}', 'reps', 10, null, false, 'Incline_Dumbbell_Press', array['Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.', 'Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.', 'Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.', 'Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells.']::text[]),
  ('Incline push-up medium', 'strength', '{body}', '{chest,core,shoulders,arms}', 'reps', 10, null, false, 'Incline_Push-Up_Medium', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands on the bar, with your hands about shoulder width apart.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
  ('Alternating floor press', 'strength', '{kettlebell}', '{chest,core,shoulders,arms}', 'reps', 10, null, true, 'Alternating_Floor_Press', array['Lie on the floor with two kettlebells next to your shoulders.', 'Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward.', 'Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell.', 'Raise the kettlebell and repeat on the opposite side.']::text[]),
  ('Close-grip EZ-bar press', 'strength', '{gym}', '{arms,chest,shoulders}', 'reps', 10, null, false, 'Close-Grip_EZ-Bar_Press', array['Lie on a flat bench with an EZ bar loaded to an appropriate weight.', 'Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.', 'Repeat.']::text[]),
  ('Standing dumbbell press', 'strength', '{dumbbells}', '{shoulders,arms}', 'reps', 10, null, false, 'Standing_Dumbbell_Press', array['Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.', 'Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.', 'Pause, and slowly return the weight to the starting position.']::text[]),
  ('Step-up with knee raise', 'strength', '{body}', '{glutes,legs}', 'reps', 10, null, true, 'Step-up_with_Knee_Raise', array['Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.', 'Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.', 'Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.']::text[]),
  ('Bodyweight walking lunge', 'strength', '{body}', '{legs,glutes}', 'reps', 10, null, true, 'Bodyweight_Walking_Lunge', array['Begin standing with your feet shoulder width apart and your hands on your hips.', 'Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.', 'Drive through the heel of your lead foot and extend both knees to raise yourself back up.', 'Step forward with your rear foot, repeating the lunge on the opposite leg.']::text[]),
  ('Standing cable wood chop', 'strength', '{gym}', '{core,shoulders}', 'reps', 10, null, false, 'Standing_Cable_Wood_Chop', array['Connect a standard handle to a tower, and move the cable to the highest pulley position.', 'With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.', 'With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.', 'In one motion, pull the handle down and across your body to your front knee while rotating your torso.', 'Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.', 'Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.', 'Repeat to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[]),
  ('Close-grip dumbbell press', 'strength', '{dumbbells}', '{arms,chest,shoulders}', 'reps', 10, null, false, 'Close-Grip_Dumbbell_Press', array['Place a dumbbell standing up on a flat bench.', 'Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.', 'Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position.', 'Initiate the movement by lowering the dumbbell to your chest.', 'Return to the starting position by extending the elbows.']::text[]),
  ('Underhand cable pulldowns', 'strength', '{gym}', '{back,arms,shoulders}', 'reps', 10, null, false, 'Underhand_Cable_Pulldowns', array['Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.', 'As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
  ('Bent over two-dumbbell row', 'strength', '{dumbbells}', '{back,arms,shoulders}', 'reps', 10, null, false, 'Bent_Over_Two-Dumbbell_Row', array['With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Incline push-up close-grip', 'strength', '{body}', '{arms,chest,shoulders}', 'reps', 10, null, false, 'Incline_Push-Up_Close-Grip', array['Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.', 'Place your hands next to one another on the bar.', 'Position your feet back from the bar with arms and body straight. This will be your starting position.', 'Keeping your body straight, lower your chest to the bar by bending the arms.', 'Return to the starting position by extending the elbows, pressing yourself back up.']::text[]),
  ('Split squat with dumbbells', 'strength', '{dumbbells}', '{legs,glutes}', 'reps', 10, null, true, 'Split_Squat_with_Dumbbells', array['Position yourself into a staggered stance with the rear foot elevated and front foot forward.', 'Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.', 'Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.', 'At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.']::text[]),
  ('External rotation with band', 'strength', '{bands}', '{shoulders}', 'reps', 10, null, false, 'External_Rotation_with_Band', array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.']::text[]),
  ('Push-ups with feet elevated', 'strength', '{body}', '{chest,shoulders,arms}', 'reps', 10, null, false, 'Push-Ups_With_Feet_Elevated', array['Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.', 'Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('Decline dumbbell bench press', 'strength', '{dumbbells}', '{chest,shoulders,arms}', 'reps', 10, null, false, 'Decline_Dumbbell_Bench_Press', array['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times. Tip: Throughout the motion, the forearms should always be perpendicular to the floor.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up..', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[]),
  ('One arm dumbbell bench press', 'strength', '{dumbbells}', '{chest,shoulders,arms}', 'reps', 10, null, true, 'One_Arm_Dumbbell_Bench_Press', array['Lie down on a flat bench with a dumbbell in one hand on top of your thigh.', 'By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.', 'Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position.', 'Bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbell at all times. Tip: Use the hand that you are not lifting with to help keep the dumbbell balance as you may struggle a bit at first. Only use your non-lifting hand if it is needed. Otherwise, keep it resting to the side.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.', 'Switch arms and repeat the movement.']::text[]),
  ('Standing dumbbell upright row', 'strength', '{dumbbells}', '{back,arms,shoulders}', 'reps', 10, null, false, 'Standing_Dumbbell_Upright_Row', array['Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.', 'Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.', 'Lower the dumbbells back down slowly to the starting position. Inhale as you perform this portion of the movement.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Close-grip barbell bench press', 'strength', '{gym}', '{arms,chest,shoulders}', 'reps', 10, null, false, 'Close-Grip_Barbell_Bench_Press', array['Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.', 'As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.', 'After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the bar back in the rack.']::text[]),
  ('Stiff leg barbell good morning', 'strength', '{gym}', '{back,glutes,legs}', 'reps', 10, null, false, 'Stiff_Leg_Barbell_Good_Morning', array['This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.', 'Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.', 'Step away from the rack and position your legs using a shoulder width medium stance. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position.', 'Keeping your legs stationary, move your torso forward by bending at the hips while inhaling. Lower your torso until it is parallel with the floor.', 'Begin to raise the bar as you exhale by elevating your torso back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Band good morning pull through', 'strength', '{bands}', '{legs,glutes,back}', 'reps', 10, null, false, 'Band_Good_Morning_Pull_Through', array['Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position.', 'Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent.', 'Return to the starting position be driving through with the hips to come back to a standing position.']::text[]),
  ('Hammer grip incline DB bench press', 'strength', '{dumbbells}', '{chest,shoulders,arms}', 'reps', 10, null, false, 'Hammer_Grip_Incline_DB_Bench_Press', array['Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.', 'Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.', 'Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.', 'As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions.', 'When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells.']::text[]),
  ('Standing alternating dumbbell press', 'strength', '{dumbbells}', '{shoulders,arms}', 'reps', 10, null, true, 'Standing_Alternating_Dumbbell_Press', array['Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position.', 'Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement.', 'After a brief pause, return the weight to the starting position.', 'Repeat for the opposite side, continuing to alternate between arms.']::text[]),
  ('Standing palm-in one-arm dumbbell press', 'strength', '{dumbbells}', '{shoulders,arms}', 'reps', 10, null, true, 'Standing_Palm-In_One-Arm_Dumbbell_Press', array['Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance.', 'Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise.', 'Slowly lift the dumbbell up until your arm is fully extended. This the starting position.', 'While inhaling lower the weight down until your arm is at a 90 degree angle again.', 'Feel the contraction for a second and then lift the weight back up towards the starting position while exhaling. Remember to hold on to the incline bench and keep your feet positioned to keep balance during the exercise.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[]),
  ('Bent over two-dumbbell row with palms in', 'strength', '{dumbbells}', '{back,arms}', 'reps', 10, null, false, 'Bent_Over_Two-Dumbbell_Row_With_Palms_In', array['With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', 'While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.', 'Slowly lower the weight again to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Calf press', 'strength', '{gym}', '{legs}', 'reps', 12, null, false, 'Calf_Press', array['Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform.', 'Select an appropriate weight, and grasp the handles. This will be your starting position.', 'Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible.', 'After a brief pause, reverse the motion and repeat.']::text[]),
  ('Arm circles', 'mobility', '{body}', '{shoulders,back}', 'hold', null, 30, false, 'Arm_Circles', array['Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.', 'Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.', 'Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.']::text[]),
  ('EZ-bar curl', 'strength', '{gym}', '{arms}', 'reps', 12, null, false, 'EZ-Bar_Curl', array['Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.', 'Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.', 'Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.', 'Then inhale and slowly lower the bar back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Elbows back', 'mobility', '{body}', '{chest,shoulders}', 'hold', null, 30, false, 'Elbows_Back', array['Stand up straight.', 'Place both hands on your lower back, fingers pointing downward and elbows out.', 'Then gently pull your elbows back aiming to touch them together.']::text[]),
  ('Spider curl', 'strength', '{gym}', '{arms}', 'reps', 12, null, false, 'Spider_Curl', array['Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off.', 'Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench.', 'Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arms on top of the pad located on the inside part of the preacher bench.', 'Use your arms to grab the barbell with a supinated grip (palms facing up) at about shoulder width apart or slightly closer from each other.', 'Slowly begin to lift the barbell upwards and exhale. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the barbell back to the starting position as your breathe in. .', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Barbell curl', 'strength', '{gym}', '{arms}', 'reps', 12, null, false, 'Barbell_Curl', array['Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.', 'While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Cable shrugs', 'strength', '{gym}', '{back}', 'reps', 12, null, false, 'Cable_Shrugs', array['Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip.', 'Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.', 'Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shoulders should be moving up and down.', 'Lower the bar back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Hammer curls', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, false, 'Hammer_Curls', array['Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.', 'After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('The straddle', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, 'The_Straddle', array['Begin in a seated, upright position. Start by extending your legs in front of you in a V.', 'With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds.']::text[]),
  ('Barbell shrug', 'strength', '{gym}', '{back}', 'reps', 12, null, false, 'Barbell_Shrug', array['Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.', 'Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Preacher curl', 'strength', '{gym}', '{arms}', 'reps', 12, null, false, 'Preacher_Curl', array['To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.', 'With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.', 'As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.', 'As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Reverse flyes', 'strength', '{dumbbells}', '{shoulders}', 'reps', 12, null, false, 'Reverse_Flyes', array['To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).', 'Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.', 'Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.', 'The arms should be elevated until they are parallel to the floor.', 'Feel the contraction and slowly lower the weights back down to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Dumbbell shrug', 'strength', '{dumbbells}', '{back}', 'reps', 12, null, false, 'Dumbbell_Shrug', array['Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.', 'Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.', 'Lower the dumbbells back to the original position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Spinal stretch', 'mobility', '{body}', '{back,shoulders}', 'hold', null, 30, false, 'Spinal_Stretch', array['Sit in a chair so your back is straight and your feet planted on the floor.', 'Interlace your fingers behind your head, elbows out and your chin down.', 'Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.', 'Return to upright position and then repeat for your other side.']::text[]),
  ('Thigh abductor', 'strength', '{gym}', '{glutes}', 'reps', 12, null, false, 'Thigh_Abductor', array['To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them away from each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Thigh adductor', 'strength', '{gym}', '{legs,glutes}', 'reps', 12, null, false, 'Thigh_Adductor', array['To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.', 'Slowly press against the machine with your legs to move them towards each other while exhaling.', 'Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Upward stretch', 'mobility', '{body}', '{shoulders,chest,back}', 'hold', null, 30, false, 'Upward_Stretch', array['Extend both hands straight above your head, palms touching.', 'Slowly push your hands up and back, keeping your back straight.']::text[]),
  ('90/90 hamstring', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, '90_90_Hamstring', array['Lie on your back, with one leg extended straight out.', 'With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.', 'Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.', 'Repeat for 10-20 repetitions, and then switch to the other leg.']::text[]),
  ('Seated leg curl', 'strength', '{gym}', '{legs}', 'reps', 12, null, false, 'Seated_Leg_Curl', array['Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.', 'Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.', 'As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.', 'Slowly return to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Triceps stretch', 'mobility', '{body}', '{arms,back}', 'hold', null, 30, false, 'Triceps_Stretch', array['Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides.']::text[]),
  ('Dancer''s stretch', 'mobility', '{body}', '{back,glutes}', 'hold', null, 30, true, 'Dancers_Stretch', array['Sit up on the floor.', 'Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor.', 'Place your left arm on your right leg and your right hand on the floor.', 'Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.']::text[]),
  ('Runner''s stretch', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, 'Runners_Stretch', array['It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor.', 'Keep the front heel on the floor (if it lifts up, scoot your other leg further back).', 'Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.']::text[]),
  ('Scapular pull-up', 'strength', '{body}', '{back}', 'reps', 12, null, false, 'Scapular_Pull-Up', array['Take a pronated grip on a pull-up bar.', 'From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion.', 'Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.']::text[]),
  ('Shoulder stretch', 'mobility', '{body}', '{shoulders}', 'hold', null, 30, false, 'Shoulder_Stretch', array['Reach your left arm across your body and hold it straight.']::text[]),
  ('Body tricep press', 'strength', '{body}', '{arms}', 'reps', 12, null, false, 'Body_Tricep_Press', array['Position a bar in a rack at chest height.', 'Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position.', 'Begin by flexing the elbow, lowering yourself towards the bar.', 'Pause, and then reverse the motion by extending the elbows.', 'Progress from bodyweight by adding chains over your shoulders.']::text[]),
  ('Seated calf raise', 'strength', '{gym}', '{legs}', 'reps', 12, null, false, 'Seated_Calf_Raise', array['Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.', 'Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.', 'Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.', 'Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.', 'Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Side neck stretch', 'mobility', '{body}', '{shoulders}', 'hold', null, 30, true, 'Side_Neck_Stretch', array['Start with your shoulders relaxed, gently tilt your head towards your shoulder.', 'Assist stretch with a gentle pull on the side of the head.']::text[]),
  ('Standing leg curl', 'strength', '{gym}', '{legs}', 'reps', 12, null, false, 'Standing_Leg_Curl', array['Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad.', 'Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your starting position.', 'As you exhale, curl your right leg up as far as possible without lifting the upper leg from the pad. Once you hit the fully contracted position, hold it for a second.', 'As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions.', 'Perform the same exercise now for the left leg.']::text[]),
  ('Dumbbell side bend', 'strength', '{dumbbells}', '{core}', 'reps', 12, null, false, 'Dumbbell_Side_Bend', array['Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position.', 'While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary.', 'Now repeat the movement but bending to the left instead. Hold for a second and come back to the starting position.', 'Repeat for the recommended amount of repetitions and then change hands.']::text[]),
  ('Hug knees to chest', 'mobility', '{body}', '{back,glutes}', 'hold', null, 30, false, 'Hug_Knees_To_Chest', array['Lie down on your back and pull both knees up to your chest.', 'Hold your arms under the knees, not over (that would put to much pressure on your knee joints).', 'Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles.']::text[]),
  ('Upper back stretch', 'mobility', '{body}', '{back}', 'hold', null, 30, false, 'Upper_Back_Stretch', array['Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward.']::text[]),
  ('Band hip adductions', 'strength', '{bands}', '{legs}', 'reps', 12, null, false, 'Band_Hip_Adductions', array['Anchor a band around a solid post or other object.', 'Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.', 'Stand up straight and hold onto the post if needed. This will be your starting position.', 'Keeping the knee straight, raise your right legs out to the side as far as you can.', 'Return to the starting position and repeat for the desired rep count.', 'Switch sides.']::text[]),
  ('Concentration curls', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, true, 'Concentration_Curls', array['Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.', 'Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.', 'Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm.']::text[]),
  ('Middle back stretch', 'mobility', '{body}', '{back,core}', 'hold', null, 30, false, 'Middle_Back_Stretch', array['Stand so your feet are shoulder width apart and your hands are on your hips.', 'Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.']::text[]),
  ('Seated calf stretch', 'mobility', '{body}', '{legs,back}', 'hold', null, 30, true, 'Seated_Calf_Stretch', array['Sit up straight on an exercise mat.', 'Bend one knee and put that foot on the floor to stabilize the torso.', 'Straighten your other leg and flex your ankle.', 'Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides.']::text[]),
  ('Tricep side stretch', 'mobility', '{body}', '{arms,shoulders}', 'hold', null, 30, true, 'Tricep_Side_Stretch', array['Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm.']::text[]),
  ('Dynamic back stretch', 'mobility', '{body}', '{back}', 'hold', null, 30, false, 'Dynamic_Back_Stretch', array['Stand with your feet shoulder width apart. This will be your starting position.', 'Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head.']::text[]),
  ('Incline hammer curls', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, false, 'Incline_Hammer_Curls', array['Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position.', 'Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary.', 'Continue to the top of the movement and pause, then slowly return to the start position.']::text[]),
  ('Knee across the body', 'mobility', '{body}', '{glutes,back}', 'hold', null, 30, true, 'Knee_Across_The_Body', array['Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.)', 'Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides.']::text[]),
  ('One arm against wall', 'mobility', '{body}', '{back}', 'hold', null, 30, true, 'One_Arm_Against_Wall', array['From a standing position, place a bent arm against a wall or doorway.', 'Slowly lean toward your arm until you feel a stretch in your lats.']::text[]),
  ('Seated dumbbell curl', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, false, 'Seated_Dumbbell_Curl', array['Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.', 'Rotate the palms of the hands so that they are facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.', 'Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Seated triceps press', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, false, 'Seated_Triceps_Press', array['Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.', 'Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Standing calf raises', 'strength', '{gym}', '{legs}', 'reps', 12, null, false, 'Standing_Calf_Raises', array['Adjust the padded lever of the calf raise machine to fit your height.', 'Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.', 'Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.', 'Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Standing hip circles', 'mobility', '{body}', '{glutes,legs}', 'hold', null, 30, false, 'Standing_Hip_Circles', array['Begin standing on one leg, holding to a vertical support.', 'Raise the unsupported knee to 90 degrees. This will be your starting position.', 'Open the hip as far as possible, attempting to make a big circle with your knee.', 'Perform this movement slowly for a number of repetitions, and repeat on the other side.']::text[]),
  ('Standing hip flexors', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, 'Standing_Hip_Flexors', array['Stand up straight with the spine vertical, the left foot slightly in front of the right.', 'Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides.']::text[]),
  ('Standing pelvic tilt', 'mobility', '{body}', '{back,glutes}', 'hold', null, 30, false, 'Standing_Pelvic_Tilt', array['Start off with your feet hip-distance apart.', 'Bend your knees slightly to keep them soft and springy.', 'You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch.']::text[]),
  ('Alternate hammer curl', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, true, 'Alternate_Hammer_Curl', array['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[]),
  ('Dynamic chest stretch', 'mobility', '{body}', '{chest,back}', 'hold', null, 30, false, 'Dynamic_Chest_Stretch', array['Stand with your hands together, arms extended directly in front of you. This will be your starting position.', 'Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so.']::text[]),
  ('Incline dumbbell curl', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, false, 'Incline_Dumbbell_Curl', array['Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.', 'While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Cross body hammer curl', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, false, 'Cross_Body_Hammer_Curl', array['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.', 'While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.', 'Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.', 'Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[]),
  ('Single leg glute bridge', 'strength', '{body}', '{glutes,legs}', 'reps', 12, null, true, 'Single_Leg_Glute_Bridge', array['Lay on the floor with your feet flat and knees bent.', 'Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.', 'Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.', 'Extend as far as possible, pause and then return to the starting position.']::text[]),
  ('Chair lower back stretch', 'mobility', '{body}', '{back}', 'hold', null, 30, false, 'Chair_Lower_Back_Stretch', array['Sit upright on a chair.', 'Bend to one side with your arm over your head. You can hold onto the chair with your free hand.', 'Hold for 10 seconds, and repeat for your other side.']::text[]),
  ('Side lying groin stretch', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, 'Side_Lying_Groin_Stretch', array['Start off by lying on your right side and bend your right knee in front of you to stabilize the torso.', 'Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder).', 'Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides.']::text[]),
  ('Side-lying floor stretch', 'mobility', '{body}', '{back}', 'hold', null, 30, true, 'Side-Lying_Floor_Stretch', array['First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright).', 'Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides.']::text[]),
  ('Tricep dumbbell kickback', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, true, 'Tricep_Dumbbell_Kickback', array['Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.', 'Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.', 'After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('Barbell seated calf raise', 'strength', '{gym}', '{legs}', 'reps', 12, null, false, 'Barbell_Seated_Calf_Raise', array['Place a block about 12 inches in front of a flat bench.', 'Sit on the bench and place the ball of your feet on the block.', 'Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position.', 'Raise up on your toes as high as possible as you squeeze the calves and as you breathe out.', 'After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('On your side quad stretch', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, 'On_Your_Side_Quad_Stretch', array['Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).', 'Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.']::text[]),
  ('Internal rotation with band', 'strength', '{bands}', '{shoulders}', 'reps', 12, null, false, 'Internal_Rotation_with_Band', array['Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away.', 'Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.', 'With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position.', 'Execute the movement by rotating your arm in a forehand motion, keeping your elbow in place.', 'Continue as far as you are able, pause, and then return to the starting position.']::text[]),
  ('Calf stretch hands against wall', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, 'Calf_Stretch_Hands_Against_Wall', array['Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.', 'Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.', 'Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.']::text[]),
  ('Calf stretch elbows against wall', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, 'Calf_Stretch_Elbows_Against_Wall', array['Stand facing a wall from a couple feet away.', 'Lean against the wall, placing your weight on your forearms.', 'Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.']::text[]),
  ('Standing towel triceps extension', 'strength', '{body}', '{arms}', 'reps', 12, null, false, 'Standing_Towel_Triceps_Extension', array['To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.', 'Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Dumbbell seated one-leg calf raise', 'strength', '{dumbbells}', '{legs}', 'reps', 12, null, true, 'Dumbbell_Seated_One-Leg_Calf_Raise', array['Place a block on the floor about 12 inches from a flat bench.', 'Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.', 'Now place the ball of your left foot on the block. This will be your starting position.', 'Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.', 'Slowly return to the starting position, stretching as far down as possible.', 'Repeat for your prescribed number of repetitions and then repeat with the right leg.']::text[]),
  ('Seated dumbbell palms-up wrist curl', 'strength', '{dumbbells}', '{arms}', 'reps', 12, null, false, 'Seated_Dumbbell_Palms-Up_Wrist_Curl', array['Start out by placing two dumbbells on the floor in front of a flat bench.', 'Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.', 'Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs.', 'Start out by curling your wrist upwards and exhaling.', 'Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this part of the exercise. Tip: Your forearms should be stationary as your wrist is the only movement needed to perform this exercise.', 'Repeat for the recommended amount of repetitions.', 'When finished, simply lower the dumbbells to the floor.']::text[]),
  ('Standing gastrocnemius calf stretch', 'mobility', '{body}', '{legs}', 'hold', null, 30, true, 'Standing_Gastrocnemius_Calf_Stretch', array['Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight.', 'Support your weight on your left leg and place your left hand on your left thigh.', 'Pull your right toes toward your knee until you feel a stretch in your calf.']::text[]),
  ('Standing one-arm dumbbell triceps extension', 'strength', '{dumbbells}', '{arms,chest,shoulders}', 'reps', 12, null, true, 'Standing_One-Arm_Dumbbell_Triceps_Extension', array['To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head.', 'This will be your starting position.', 'Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearm touch your bicep. Tip: The upper arm should remain stationary and only the forearm should move. Breathe in as you perform this step.', 'Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.', 'Repeat for the recommended amount of repetitions.', 'Switch arms and repeat the exercise.']::text[]),
  ('Good morning', 'strength', '{gym}', '{legs,core,glutes,back}', 'reps', 10, null, false, 'Good_Morning', array['Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack.', 'Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.', 'Reverse the motion by extending through the hips with your glutes and hamstrings. Continue until you have returned to the starting position.']::text[]),
  ('Sumo deadlift', 'strength', '{gym}', '{legs,arms,glutes,back}', 'reps', 10, null, false, 'Sumo_Deadlift', array['Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.', 'Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.', 'As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.', 'Return the weight to the ground by bending at the hips and controlling the weight on the way down.']::text[]),
  ('Lunge pass through', 'strength', '{kettlebell}', '{legs,glutes}', 'reps', 10, null, true, 'Lunge_Pass_Through', array['Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position.', 'Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground.', 'As you lunge, pass the kettlebell under your front leg to your opposite hand.', 'Pressing through the heel of your foot, return to the starting position.', 'Repeat the movement for the recommended amount of repetitions, alternating legs.']::text[]),
  ('Barbell glute bridge', 'strength', '{gym}', '{glutes,legs}', 'reps', 10, null, false, 'Barbell_Glute_Bridge', array['Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor.', 'Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.', 'Extend as far as possible, then reverse the motion to return to the starting position.']::text[]),
  ('One-arm kettlebell row', 'strength', '{kettlebell}', '{back,arms}', 'reps', 10, null, true, 'One-Arm_Kettlebell_Row', array['Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.']::text[]),
  ('Two-arm kettlebell row', 'strength', '{kettlebell}', '{back,arms}', 'reps', 10, null, false, 'Two-Arm_Kettlebell_Row', array['Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position.', 'Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.']::text[]),
  ('Wide-grip rear pull-up', 'strength', '{body}', '{back,arms,shoulders}', 'reps', 10, null, false, 'Wide-Grip_Rear_Pull-Up', array['Grab the pull-up bar with the palms facing forward using a wide grip.', 'As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position.', 'Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.', 'After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.', 'Repeat this motion for the prescribed amount of repetitions.']::text[]),
  ('Kettlebell arnold press', 'strength', '{kettlebell}', '{shoulders,arms}', 'reps', 10, null, false, 'Kettlebell_Arnold_Press', array['Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward.', 'Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion.', 'Return the kettlebell to the starting position, with the palm facing in.']::text[]),
  ('Kettlebell seated press', 'strength', '{kettlebell}', '{shoulders,arms}', 'reps', 10, null, false, 'Kettlebell_Seated_Press', array['Sit on the floor and spread your legs out comfortably.', 'Clean one kettlebell to your shoulder.', 'Press the kettlebell up and out until it is locked out overhead. Return to the starting position.']::text[]),
  ('Dumbbell squat to a bench', 'strength', '{dumbbells}', '{legs,glutes,back}', 'reps', 10, null, false, 'Dumbbell_Squat_To_A_Bench', array['Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs).', 'Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.', 'Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until you slightly touch the bench behind you. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.', 'Begin to raise the bar as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('Kettlebell sumo high pull', 'strength', '{kettlebell}', '{back,legs,glutes,shoulders}', 'reps', 10, null, false, 'Kettlebell_Sumo_High_Pull', array['Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position.', 'Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.']::text[]),
  ('Kettlebell one-legged deadlift', 'strength', '{kettlebell}', '{legs,glutes,back}', 'reps', 10, null, true, 'Kettlebell_One-Legged_Deadlift', array['Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.', 'Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.', 'Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position.']::text[]),
  ('One-arm kettlebell floor press', 'strength', '{kettlebell}', '{chest,arms}', 'reps', 10, null, true, 'One-Arm_Kettlebell_Floor_Press', array['Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.', 'Press the kettlebell straight up toward the ceiling, rotating your wrist.', 'Lower the kettlebell back to the starting position and repeat.']::text[]),
  ('Kettlebell pass between the legs', 'strength', '{kettlebell}', '{core,glutes,legs,shoulders}', 'reps', 10, null, false, 'Kettlebell_Pass_Between_The_Legs', array['Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat.', 'Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a "W". Go back and forth for several repetitions.']::text[]),
  ('Front squats with two kettlebells', 'strength', '{kettlebell}', '{legs,glutes}', 'reps', 10, null, false, 'Front_Squats_With_Two_Kettlebells', array['Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so.', 'Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up.', 'Rise back up by driving through your heels and repeat.']::text[]),
  ('Push-ups, close triceps position', 'strength', '{body}', '{arms,chest,shoulders}', 'reps', 10, null, false, 'Push-Ups_-_Close_Triceps_Position', array['Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length.', 'Lower yourself until your chest almost touches the floor as you inhale.', 'Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.', 'After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.']::text[]),
  ('Kettlebell figure 8', 'strength', '{kettlebell}', '{core,legs,shoulders}', 'reps', 10, null, false, 'Kettlebell_Figure_8', array['Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat.', 'Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions.']::text[]),
  ('Calf raise on a dumbbell', 'strength', '{dumbbells}', '{legs}', 'reps', 12, null, false, 'Calf_Raise_On_A_Dumbbell', array['Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise.', 'Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.', 'Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement. Contract the calf hard at the top and hold for a second. Tip: As you come up, roll the dumbbell slightly backward.', 'Now inhale as you roll the dumbbell slightly forward as you come down to get a better stretch.', 'Repeat for the recommended amount of repetitions.']::text[]),
  ('One-legged cable kickback', 'strength', '{gym}', '{glutes,legs}', 'reps', 12, null, true, 'One-Legged_Cable_Kickback', array['Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle.', 'Face the weight stack from a distance of about two feet, grasping the steel frame for support.', 'While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction.', 'Now slowly bring your working leg forward, resisting the pull of the cable until you reach the starting position.', 'Repeat for the recommended amount of repetitions.', 'Switch legs and repeat the movement for the other side.']::text[]),
  ('Alternating kettlebell row', 'strength', '{kettlebell}', '{back,arms}', 'reps', 12, null, true, 'Alternating_Kettlebell_Row', array['Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles.', 'Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage.', 'Lower the kettlebell in the working arm and repeat with your other arm.']::text[])
